import React, { useCallback, useEffect, useState } from "react";
import { Link, Navigate, useSearchParams } from "react-router-dom";
import { LayoutDashboard, LogOut, Package, Shield, ShoppingCart, Store, Users } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { apiFetch } from "./api";
import { CATEGORY_LABELS } from "./catalog";
import { formatGhc } from "./money";
import { h, f } from "./h";
import { Badge, Button, Field, GlassCard, GlassPanel, InlineNotice, TextArea, ThemeToggleButton } from "./ui";

function humanizeOrderStatus(s) {
  return String(s || "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function formatListingStatus(s) {
  if (s === "pending_approval") return "Pending";
  if (s === "active") return "Live";
  if (s === "rejected") return "Rejected";
  if (s === "draft") return "Draft";
  return s || "—";
}

function listingStatusTone(s) {
  if (s === "active") return "success";
  if (s === "pending_approval") return "warn";
  if (s === "rejected") return "danger";
  if (s === "draft") return "warn";
  return "neutral";
}

const TABS = [
  { id: "dashboard", label: "Dashboard", Icon: LayoutDashboard },
  { id: "users", label: "Users", Icon: Users },
  { id: "listings", label: "Listings", Icon: Package },
  { id: "orders", label: "Orders", Icon: ShoppingCart }
];

function StatCard({ title, value, sub }) {
  return h(GlassPanel, { className: "min-h-[100px] !p-4 sm:!p-5" }, [
    h("p", { key: "t", className: "text-xs font-medium uppercase tracking-wide text-slate-500 dark:text-slate-400" }, title),
    h("p", { key: "v", className: "mt-2 font-display text-2xl font-bold text-slate-900 dark:text-white" }, value),
    sub
      ? h("p", { key: "s", className: "mt-1 text-xs text-slate-500 dark:text-slate-400" }, sub)
      : null
  ]);
}

export function AdminPage() {
  const { user, accessToken, logout } = useAuth();
  const { confirm, alert } = useNotice();
  const [searchParams, setSearchParams] = useSearchParams();
  const tab = searchParams.get("tab") || "dashboard";
  const setTab = (id) => {
    if (id === "dashboard") setSearchParams({}, { replace: true });
    else setSearchParams({ tab: id }, { replace: true });
  };

  const [err, setErr] = useState("");
  const [dashboard, setDashboard] = useState(null);
  const [users, setUsers] = useState([]);
  const [usersPage, setUsersPage] = useState(1);
  const [usersTotal, setUsersTotal] = useState(0);
  const [usersLimit] = useState(25);
  const [listings, setListings] = useState([]);
  const [listingsPage, setListingsPage] = useState(1);
  const [listingsTotal, setListingsTotal] = useState(0);
  const [listingsLimit] = useState(20);
  const [listFilter, setListFilter] = useState("pending_approval");
  const [orders, setOrders] = useState([]);
  const [ordersPage, setOrdersPage] = useState(1);
  const [ordersTotal, setOrdersTotal] = useState(0);
  const [ordersLimit] = useState(25);
  const [loading, setLoading] = useState(true);

  const [rejectId, setRejectId] = useState(null);
  const [rejectReason, setRejectReason] = useState("");

  const loadDashboard = useCallback(() => {
    if (!accessToken) return;
    return apiFetch("/api/admin/dashboard", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => setDashboard(d))
      .catch((ex) => setErr(ex.message || "Failed to load dashboard"));
  }, [accessToken]);

  const loadUsers = useCallback(() => {
    if (!accessToken) return;
    return apiFetch(`/api/admin/users?page=${usersPage}&limit=${usersLimit}`, { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        setUsers(d.users || []);
        setUsersTotal(d.total || 0);
      })
      .catch((ex) => setErr(ex.message || "Failed to load users"));
  }, [accessToken, usersPage, usersLimit]);

  const loadListings = useCallback(() => {
    if (!accessToken) return;
    const st = listFilter === "all" ? "all" : listFilter;
    return apiFetch(`/api/admin/products?status=${encodeURIComponent(st)}&page=${listingsPage}&limit=${listingsLimit}`, {
      headers: { Authorization: `Bearer ${accessToken}` }
    })
      .then((d) => {
        setListings(d.products || []);
        setListingsTotal(d.total || 0);
      })
      .catch((ex) => setErr(ex.message || "Failed to load listings"));
  }, [accessToken, listFilter, listingsPage, listingsLimit]);

  const loadOrders = useCallback(() => {
    if (!accessToken) return;
    return apiFetch(`/api/admin/orders?page=${ordersPage}&limit=${ordersLimit}`, { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((d) => {
        setOrders(d.orders || []);
        setOrdersTotal(d.total || 0);
      })
      .catch((ex) => setErr(ex.message || "Failed to load orders"));
  }, [accessToken, ordersPage, ordersLimit]);

  useEffect(() => {
    if (!accessToken) return;
    setLoading(true);
    setErr("");
    const p = (() => {
      if (tab === "dashboard") return loadDashboard();
      if (tab === "users") return loadUsers();
      if (tab === "listings") return loadListings();
      if (tab === "orders") return loadOrders();
      return Promise.resolve();
    })();
    Promise.resolve(p).finally(() => setLoading(false));
  }, [accessToken, tab, loadDashboard, loadUsers, loadListings, loadOrders]);

  if (!user || user.role !== "admin") {
    if (!accessToken) return h(Navigate, { to: "/login", replace: true, state: { from: "/admin" } });
    return h(
      "div",
      { className: "flex min-h-screen items-center justify-center bg-night-950 px-4 text-slate-200" },
      h("p", { className: "text-center" }, "You don’t have access to the admin area.")
    );
  }

  const patchUser = async (id, body) => {
    try {
      await apiFetch(`/api/admin/users/${id}`, { method: "PATCH", headers: { Authorization: `Bearer ${accessToken}` }, json: body });
      await loadUsers();
    } catch (ex) {
      await alert(ex.message || "Update failed", { variant: "error", title: "User" });
    }
  };

  const onUserAction = async (u, nextStatus) => {
    if (nextStatus === "banned") {
      const ok = await confirm(`Ban ${u.displayName || u.email || u.id}? They won’t be able to sign in.`, {
        title: "Ban user?",
        confirmLabel: "Ban"
      });
      if (!ok) return;
    }
    await patchUser(u.id, { accountStatus: nextStatus });
  };

  const approve = async (id) => {
    try {
      await apiFetch(`/api/admin/products/${id}/approve`, { method: "POST", headers: { Authorization: `Bearer ${accessToken}` }, json: {} });
      setRejectId(null);
      setRejectReason("");
      await loadListings();
      await loadDashboard();
    } catch (ex) {
      await alert(ex.message || "Approve failed", { variant: "error" });
    }
  };

  const submitReject = async () => {
    if (!rejectId) return;
    const reason = rejectReason.trim();
    if (reason.length < 1) {
      await alert("Add a short reason for the seller.", { variant: "warning", title: "Reason required" });
      return;
    }
    try {
      await apiFetch(`/api/admin/products/${rejectId}/reject`, {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { reason }
      });
      setRejectId(null);
      setRejectReason("");
      await loadListings();
      await loadDashboard();
    } catch (ex) {
      await alert(ex.message || "Reject failed", { variant: "error" });
    }
  };

  const uTotal = dashboard?.users?.total ?? "—";
  const buyers = dashboard?.users?.buyers ?? "—";
  const sellers = dashboard?.users?.sellers ?? "—";
  const orderTotal = dashboard?.orders?.total ?? "—";
  const rev = dashboard?.revenue?.platformCommissionTotal;
  const revPct = dashboard?.revenue?.platformCommissionPercent;
  const activeList = dashboard?.products?.active ?? "—";
  const pending = dashboard?.products?.pendingApproval ?? "—";
  const reports = dashboard?.flags?.openReports ?? 0;
  const recentOrders = (dashboard?.recent?.orders || []).slice(0, 6);

  return h("div", { className: "relative min-h-screen overflow-x-hidden" }, [
    h("div", {
      key: "top",
      className: "sticky top-0 z-30 border-b border-white/10 bg-slate-100/80 backdrop-blur dark:bg-night-950/80"
    }, [
      h("div", { className: "mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-3 px-4 py-3 sm:px-6" }, [
        h("div", { className: "flex min-w-0 items-center gap-2" }, [
          h(Shield, { className: "h-6 w-6 shrink-0 text-amber-500" }),
          h("span", { className: "font-display text-lg font-semibold text-slate-900 dark:text-white" }, "Admin"),
          h("span", { className: "sr-only" }, "Campus Mart")
        ]),
        h("div", { className: "flex flex-wrap items-center gap-2" }, [
          h(
            Link,
            {
              to: "/",
              className: "inline-flex items-center gap-1 rounded-2xl border border-slate-300/80 px-3 py-2 text-sm text-slate-800 hover:bg-white/50 dark:border-white/15 dark:text-slate-100 dark:hover:bg-white/10"
            },
            [h(Store, { key: "i", className: "h-4 w-4" }), h("span", { key: "l" }, "Storefront")]
          ),
          h(ThemeToggleButton, { key: "th" }),
          h(
            Button,
            {
              key: "out",
              variant: "ghost",
              className: "!min-h-[40px] !px-3",
              onClick: () => logout()
            },
            [h(LogOut, { key: "lo", className: "h-4 w-4" }), "Log out"]
          )
        ])
      ])
    ]),

    h("div", { key: "main", className: "mx-auto max-w-6xl px-4 py-6 sm:px-6" }, [
      err ? h(InlineNotice, { key: "e", variant: "error", className: "mb-4", onDismiss: () => setErr("") }, err) : null,
      h("div", { key: "tabs", className: "mb-6 flex flex-wrap gap-2" },
        TABS.map(({ id, label, Icon }) =>
          h(
            Button,
            {
              key: id,
              variant: tab === id ? "primary" : "ghost",
              className: "!min-h-[40px] !rounded-full !px-4",
              onClick: () => setTab(id)
            },
            [h(Icon, { key: "ic", className: "h-4 w-4" }), label]
          )
        )
      ),

      loading && h("p", { key: "ld", className: "mb-4 text-sm text-slate-500" }, "Loading…"),

      tab === "dashboard" &&
        !loading &&
        h(f, { key: "dash" }, [
          h("div", { className: "mb-4" }, h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Overview")),
          h("div", { className: "grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3" }, [
            h(StatCard, { key: "u", title: "Total users", value: String(uTotal), sub: `Buyers ${buyers} · Sellers ${sellers}` }),
            h(StatCard, { key: "o", title: "Orders (all time)", value: String(orderTotal) }),
            h(StatCard, {
              key: "r",
              title: "Platform revenue (fees)",
              value: rev != null ? formatGhc(rev) : "—",
              sub: revPct != null ? `Commission model: ${revPct}% of line total` : null
            }),
            h(StatCard, { key: "a", title: "Active listings", value: String(activeList) }),
            h(StatCard, { key: "p", title: "Pending approval", value: String(pending), sub: "New products waiting for you" }),
            h(StatCard, { key: "rep", title: "Open reports", value: String(reports), sub: "Complaints (placeholder until wired)" })
          ]),
          h("h2", { className: "mb-2 mt-8 text-lg font-semibold text-slate-900 dark:text-white" }, "Recent orders"),
          h(
            GlassCard,
            { key: "ro", className: "!p-0" },
            recentOrders.length === 0
              ? h("p", { className: "p-4 text-sm text-slate-500" }, "No orders yet.")
              : h("div", { className: "divide-y divide-white/10" },
                  recentOrders.map((o) =>
                    h("div", { key: o.id, className: "flex flex-wrap items-center justify-between gap-2 px-4 py-3" }, [
                      h("span", { className: "font-mono text-sm text-slate-600 dark:text-slate-300" }, `#${String(o.id).slice(-8)}`),
                      o.total != null
                        ? h("span", { className: "text-sm text-slate-900 dark:text-white" }, formatGhc(o.total))
                        : null,
                      h(Badge, { tone: "neutral" }, humanizeOrderStatus(o.status))
                    ])
                  )
                )
          )
        ]),

      tab === "users" &&
        !loading &&
        h(f, { key: "u-tab" }, [
          h("h1", { className: "mb-4 font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Users"),
          h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[820px] text-left text-sm" }, [
            h("thead", { className: "border-b border-white/10 bg-white/20 text-xs uppercase text-slate-500 dark:bg-white/5 dark:text-slate-400" }, h("tr", null, [
              h("th", { className: "px-3 py-3" }, "Name / email"),
              h("th", { className: "px-3 py-3" }, "Role"),
              h("th", { className: "px-3 py-3" }, "Account"),
              h("th", { className: "px-3 py-3" }, "Verified seller"),
              h("th", { className: "px-3 py-3" }, "Actions")
            ])),
            h(
              "tbody",
              { className: "divide-y divide-white/10" },
              users.map((u) =>
                h("tr", { key: u.id, className: "hover:bg-white/5" }, [
                  h("td", { className: "px-3 py-2" }, [
                    h("div", { className: "font-medium text-slate-900 dark:text-white" }, u.displayName || "—"),
                    h("div", { className: "text-xs text-slate-500" }, u.email || u.phone || u.id)
                  ]),
                  h("td", { className: "px-3 py-2" }, h(Badge, { tone: "neutral" }, u.role)),
                  h("td", { className: "px-3 py-2" }, h(Badge, { tone: u.accountStatus === "active" ? "success" : "danger" }, u.accountStatus || "active")),
                  h("td", { className: "px-3 py-2" },
                    u.role === "seller" || u.role === "admin"
                      ? h(Badge, { tone: u.sellerVerified ? "success" : "warn" }, u.sellerVerified ? "Yes" : "No")
                      : "—"
                  ),
                  h("td", { className: "px-3 py-2" }, h("div", { className: "flex flex-wrap gap-1" }, [
                    (u.accountStatus === "suspended" || u.accountStatus === "banned") &&
                      h(
                        Button,
                        {
                          key: "act",
                          variant: "ghost",
                          className: "!min-h-[32px] !px-2 !text-xs",
                          onClick: () => patchUser(u.id, { accountStatus: "active" })
                        },
                        "Restore"
                      ),
                    u.accountStatus !== "suspended" &&
                      h(
                        Button,
                        {
                          key: "sus",
                          variant: "ghost",
                          className: "!min-h-[32px] !px-2 !text-xs",
                          onClick: () => onUserAction(u, "suspended")
                        },
                        "Suspend"
                      ),
                    u.accountStatus !== "banned" &&
                      h(
                        Button,
                        {
                          key: "ban",
                          variant: "danger",
                          className: "!min-h-[32px] !px-2 !text-xs",
                          onClick: () => onUserAction(u, "banned")
                        },
                        "Ban"
                      ),
                    (u.role === "seller" || u.role === "admin") &&
                      h(
                        Button,
                        {
                          key: "ver",
                          variant: "ghost",
                          className: "!min-h-[32px] !px-2 !text-xs",
                          onClick: () => patchUser(u.id, { sellerVerified: !u.sellerVerified })
                        },
                        u.sellerVerified ? "Unverify" : "Verify"
                      )
                  ]))
                ])
              )
            )
          ])),
          h("div", { className: "mt-3 flex items-center justify-between text-sm text-slate-500" }, [
            h("span", {}, `Page ${usersPage} · ${usersTotal} users`),
            h("div", { className: "flex gap-2" }, [
              h(Button, { variant: "ghost", className: "!min-h-[36px]", disabled: usersPage <= 1, onClick: () => setUsersPage((p) => Math.max(1, p - 1)) }, "Prev"),
              h(Button, { variant: "ghost", className: "!min-h-[36px]", disabled: usersPage * usersLimit >= usersTotal, onClick: () => setUsersPage((p) => p + 1) }, "Next")
            ])
          ])
        ]),

      tab === "listings" &&
        !loading &&
        h(f, { key: "l-tab" }, [
          h("div", { className: "mb-4 flex flex-wrap items-center justify-between gap-2" }, [
            h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Listings"),
            h("div", { className: "flex flex-wrap items-center gap-2" }, [
              h(
                "label",
                { className: "text-sm text-slate-600 dark:text-slate-300" },
                "Filter: ",
                h("select", {
                  className:
                    "ml-1 rounded-2xl border border-slate-300/80 bg-white/80 px-3 py-2 text-sm text-slate-900 dark:border-white/15 dark:bg-night-900/80 dark:text-white",
                  value: listFilter,
                  onChange: (e) => {
                    setListFilter(e.target.value);
                    setListingsPage(1);
                  }
                }, [
                  h("option", { value: "pending_approval" }, "Pending approval"),
                  h("option", { value: "active" }, "Live"),
                  h("option", { value: "rejected" }, "Rejected"),
                  h("option", { value: "draft" }, "Drafts"),
                  h("option", { value: "all" }, "All")
                ])
              )
            ])
          ]),
          h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[900px] text-left text-sm" }, [
            h("thead", { className: "border-b border-white/10 bg-white/20 text-xs uppercase text-slate-500 dark:bg-white/5" }, h("tr", null, [
              h("th", { className: "px-3 py-3" }, "Product"),
              h("th", { className: "px-3 py-3" }, "Seller"),
              h("th", { className: "px-3 py-3" }, "Category"),
              h("th", { className: "px-3 py-3" }, "Status"),
              h("th", { className: "px-3 py-3" }, "Price"),
              h("th", { className: "px-3 py-3" }, "Actions")
            ])),
            h(
              "tbody",
              { className: "divide-y divide-white/10" },
              listings.map((p) =>
                h("tr", { key: p.id, className: "align-top hover:bg-white/5" }, [
                  h("td", { className: "px-3 py-2" }, [
                    h("div", { className: "font-medium text-slate-900 dark:text-white" }, p.name),
                    p.rejectionReason && p.status === "rejected"
                      ? h("p", { className: "mt-1 text-xs text-rose-600 dark:text-rose-300" }, `Reason: ${p.rejectionReason}`)
                      : null
                  ]),
                  h("td", { className: "px-3 py-2 text-slate-600 dark:text-slate-300" }, p.sellerLabel),
                  h("td", { className: "px-3 py-2" }, CATEGORY_LABELS[p.category] || p.category || "—"),
                  h("td", { className: "px-3 py-2" }, h(Badge, { tone: listingStatusTone(p.status) }, formatListingStatus(p.status))),
                  h("td", { className: "px-3 py-2 font-medium" }, formatGhc(p.price)),
                  h("td", { className: "px-3 py-2" }, h("div", { className: "flex flex-wrap gap-1" }, [
                    (p.status === "pending_approval" || p.status === "draft" || p.status === "rejected") &&
                      h(Button, { key: "ok", variant: "primary", className: "!min-h-[32px] !px-2 !text-xs", onClick: () => approve(p.id) }, "Approve"),
                    p.status !== "rejected" &&
                      p.status !== "active" &&
                      h(
                        Button,
                        {
                          key: "no",
                          variant: "danger",
                          className: "!min-h-[32px] !px-2 !text-xs",
                          onClick: () => {
                            setRejectId(p.id);
                            setRejectReason("");
                          }
                        },
                        "Reject"
                      )
                  ]))
                ])
              )
            )
          ])),
          rejectId &&
            h(GlassPanel, { key: "rj", className: "mt-4 border border-rose-500/30" }, [
              h("p", { className: "text-sm font-medium text-slate-900 dark:text-white" }, "Reject listing"),
              h(Field, { className: "mt-2", label: "Reason to show the seller" }, h(TextArea, { value: rejectReason, onChange: (e) => setRejectReason(e.target.value), rows: 3, placeholder: "e.g. Photos don’t show the real item." })),
              h("div", { className: "mt-3 flex gap-2" }, [
                h(Button, { onClick: submitReject, variant: "danger" }, "Submit rejection"),
                h(Button, { variant: "ghost", onClick: () => setRejectId(null) }, "Cancel")
              ])
            ]),
          h("div", { className: "mt-3 flex items-center justify-between text-sm text-slate-500" }, [
            h("span", {}, `Page ${listingsPage} · ${listingsTotal} listings`),
            h("div", { className: "flex gap-2" }, [
              h(Button, { variant: "ghost", className: "!min-h-[36px]", disabled: listingsPage <= 1, onClick: () => setListingsPage((p) => Math.max(1, p - 1)) }, "Prev"),
              h(Button, { variant: "ghost", className: "!min-h-[36px]", disabled: listingsPage * listingsLimit >= listingsTotal, onClick: () => setListingsPage((p) => p + 1) }, "Next")
            ])
          ])
        ]),

      tab === "orders" &&
        !loading &&
        h(f, { key: "o-tab" }, [
          h("h1", { className: "mb-4 font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Orders & revenue view"),
          h("p", { className: "mb-3 text-sm text-slate-500" }, "Each order shows the buyer and seller contact info already stored at checkout. Use this to help resolve issues."),
          h(GlassCard, { className: "!overflow-x-auto !p-0" }, h("table", { className: "w-full min-w-[960px] text-left text-sm" }, [
            h("thead", { className: "border-b border-white/10 bg-white/20 text-xs uppercase" }, h("tr", null, [
              h("th", { className: "px-3 py-3" }, "Order"),
              h("th", { className: "px-3 py-3" }, "Status"),
              h("th", { className: "px-3 py-3" }, "Total"),
              h("th", { className: "px-3 py-3" }, "Your fee"),
              h("th", { className: "px-3 py-3" }, "Buyer"),
              h("th", { className: "px-3 py-3" }, "Created")
            ])),
            h(
              "tbody",
              { className: "divide-y divide-white/10" },
              orders.map((o) =>
                h("tr", { key: o.id, className: "align-top hover:bg-white/5" }, [
                  h("td", { className: "px-3 py-2 font-mono" }, String(o.id).slice(-10)),
                  h("td", { className: "px-3 py-2" }, h(Badge, { tone: "neutral" }, humanizeOrderStatus(o.status))),
                  h("td", { className: "px-3 py-2 font-medium" }, o.total != null ? formatGhc(o.total) : "—"),
                  h("td", { className: "px-3 py-2" }, o.platformFeeTotal != null ? formatGhc(o.platformFeeTotal) : "—"),
                  h("td", { className: "px-3 py-2 text-slate-600 dark:text-slate-300" },
                    o.buyerContact
                      ? h("div", null, [h("div", { key: "n" }, o.buyerContact.displayName || "—"), h("div", { key: "e", className: "text-xs" }, o.buyerContact.email || "")])
                      : "—"
                  ),
                  h("td", { className: "px-3 py-2 text-slate-500" },
                    o.createdAt ? new Date(o.createdAt).toLocaleString(undefined, { dateStyle: "short", timeStyle: "short" }) : "—"
                  )
                ])
              )
            )
          ])),
          h("div", { className: "mt-3 flex items-center justify-between text-sm text-slate-500" }, [
            h("span", {}, `Page ${ordersPage} · ${ordersTotal} orders`),
            h("div", { className: "flex gap-2" }, [
              h(Button, { variant: "ghost", className: "!min-h-[36px]", disabled: ordersPage <= 1, onClick: () => setOrdersPage((p) => Math.max(1, p - 1)) }, "Prev"),
              h(Button, { variant: "ghost", className: "!min-h-[36px]", disabled: ordersPage * ordersLimit >= ordersTotal, onClick: () => setOrdersPage((p) => p + 1) }, "Next")
            ])
          ])
        ])
    ])
  ]);
}
